    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # For each interval in a, subtract all intervals in b
    result = []
    for a_start, a_end in a_intervals:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_ranges = []
            for c_start, c_end in current_ranges:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if b_end < c_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort result
    result.sort()

